namespace {
constexpr int kTileMinWidth = 250;
}

HwmonPage::HwmonPage(iwp::DeviceModel *model, QWidget *parent)
    : QWidget(parent), m_model(model), ui(std::make_unique<Ui::HwmonPage>())
{
    build();
    buildTiles();
    showInfo();
    showStatus();
    connect(m_model, &iwp::DeviceModel::valueChanged, this, [this](const QString &key) {
        if (key == QLatin1String("info"))
            showInfo();
        else if (key == QLatin1String("layout"))
            buildTiles();
        else if (key == QLatin1String("values"))
            showValues();
        else if (key == QLatin1String("sensor_count") || key == QLatin1String("period_ms"))
            showStatus();
    });
    connect(m_model, &iwp::DeviceModel::staleChanged, this, [this](const QString &key, bool stale) {
        if (key == QLatin1String("values") && stale)
            for (SensorTile *t : std::as_const(m_tiles))
                t->clearValue();
    });
    connect(m_model, &iwp::DeviceModel::statusChanged, this, [this](iwp::DeviceModel::Status s, const QString &) {
        if (s != iwp::DeviceModel::Status::Running)
            for (SensorTile *t : std::as_const(m_tiles))
                t->clearValue();
        showStatus();
    });
    connect(m_model, &iwp::DeviceModel::eventPosted, this, [this](const QString &channel, const QVariant &payload) {
        if (channel == QLatin1String("log"))
            ui->statusLabel->setText(payload.toString());
    });
}

HwmonPage::~HwmonPage() = default;   // here Ui::HwmonPage is a complete type

void HwmonPage::build()
{
    ui->setupUi(this);   // every widget of hwmonpage.ui is ui->objectName

    ui->windowCombo->addItem(tr("10 s"), 10);
    ui->windowCombo->addItem(tr("30 s"), 30);
    ui->windowCombo->addItem(tr("1 min"), 60);
    ui->windowCombo->addItem(tr("5 min"), 300);
    ui->windowCombo->addItem(tr("15 min"), 900);
    ui->windowCombo->setCurrentIndex(1);
    ui->periodSpin->setRange(hwmon::kMinPeriodMs, hwmon::kMaxPeriodMs);

    connect(ui->windowCombo, &QComboBox::currentIndexChanged, this, [this] {
        for (SensorTile *t : std::as_const(m_tiles))
            t->setWindowSeconds(ui->windowCombo->currentData().toDouble());
    });
    connect(ui->pauseCheck, &QCheckBox::toggled, this, [this](bool on) {
        for (SensorTile *t : std::as_const(m_tiles))
            t->setPaused(on);
    });
    connect(ui->settingsButton, &QPushButton::toggled, ui->settingsPanel, &QWidget::setVisible);
    connect(ui->applyButton, &QPushButton::clicked, this, &HwmonPage::apply);
    connect(ui->saveButton, &QPushButton::clicked, this, &HwmonPage::savePreset);
    connect(ui->openButton, &QPushButton::clicked, this, &HwmonPage::openPreset);
    connect(ui->presetCombo, &QComboBox::activated, this, &HwmonPage::presetChosen);
    connect(ui->defaultsButton, &QPushButton::clicked, this, [this] {
        ui->sensorsEdit->setPlainText(QString::fromStdString(hwmon::defaultSensorsText()));
        ui->infoEdit->setPlainText(QString::fromStdString(hwmon::defaultInfoText()));
        ui->periodSpin->setValue(100);
        ui->preciseCheck->setChecked(true);
    });
    refreshPresets();

    const HwmonSettings s = HwmonSettings::load();
    ui->periodSpin->setValue(s.periodMs);
    ui->preciseCheck->setChecked(s.precise);
    ui->sensorsEdit->setPlainText(s.sensorsText);
    ui->infoEdit->setPlainText(s.infoText);
}

void HwmonPage::buildTiles(bool fromDevice)
{
    qDeleteAll(m_tiles);
    m_tiles.clear();
    QList<TileSpec> specs;
    const QVariantList layout = fromDevice ? m_model->value(QStringLiteral("layout")).toList() : QVariantList();
    if (!layout.isEmpty()) {
        for (const QVariant &v : layout) {
            const QVariantMap e = v.toMap();
            TileSpec t;
            t.name = e.value("name").toString();
            t.unit = e.value("unit").toString();
            t.decimals = e.value("decimals").toInt();
            t.text = e.value("text").toBool();
            t.hasMin = e.value("hasMin").toBool();
            t.hasMax = e.value("hasMax").toBool();
            t.minV = e.value("minV").toDouble();
            t.maxV = e.value("maxV").toDouble();
            t.expect = e.value("expect").toString();
            specs.append(t);
        }
    } else {
        // Before the device has reported (or after "Apply"): one tile per line of the list; a mask shows once.
        HwmonSettings s = HwmonSettings::load();
        hwmon::Config cfg;
        QString err;
        s.toConfig(cfg, &err);   // on an error: no sensors, the message is in the settings panel
        for (const hwmon::Slot &sl : hwmon::declaredSlots(cfg)) {
            const hwmon::Sensor &x = cfg.sensors[size_t(sl.def)];
            TileSpec t;
            t.name = QString::fromStdString(sl.name);
            t.unit = QString::fromStdString(x.unit);
            t.decimals = hwmon::decimalsFor(x.divisor);
            t.text = x.text;
            t.hasMin = x.hasMin;
            t.hasMax = x.hasMax;
            t.minV = x.minV;
            t.maxV = x.maxV;
            t.expect = QString::fromStdString(x.expect);
            specs.append(t);
        }
    }
    iwp::PlotBuffer *buffer = m_model->plot(QStringLiteral("sensors"));
    for (int i = 0; i < specs.size() && buffer; ++i) {
        auto *tile = new SensorTile(specs[i], buffer, i, ui->tilesHost);
        tile->setWindowSeconds(ui->windowCombo->currentData().toDouble());
        tile->setPaused(ui->pauseCheck->isChecked());
        m_tiles.append(tile);
    }
    layoutTiles();
    showValues();
}

void HwmonPage::layoutTiles()
{
    while (ui->tilesGrid->count() > 0)
        ui->tilesGrid->takeAt(0);
    const int cols = qMax(1, ui->tilesHost->width() / kTileMinWidth);
    for (int i = 0; i < m_tiles.size(); ++i)
        ui->tilesGrid->addWidget(m_tiles[i], i / cols, i % cols);
    for (int c = 0; c < cols; ++c)
        ui->tilesGrid->setColumnStretch(c, 1);
    for (int c = cols; c < 16; ++c)
        ui->tilesGrid->setColumnStretch(c, 0);
    for (SensorTile *t : std::as_const(m_tiles))
        t->show();
}

void HwmonPage::resizeEvent(QResizeEvent *e)
{
    QWidget::resizeEvent(e);
    if (!m_tiles.isEmpty())
        layoutTiles();
}

void HwmonPage::showInfo()
{
    while (ui->infoForm->rowCount() > 0)
        ui->infoForm->removeRow(0);
    const QVariantList list = m_model->value(QStringLiteral("info")).toList();
    if (list.isEmpty()) {
        ui->infoForm->addRow(new QLabel(tr("The versions are read after connecting.")));
        return;
    }
    for (const QVariant &v : list) {
        const QVariantMap e = v.toMap();
        auto *l = new QLabel(e.value("text").toString());
        l->setTextInteractionFlags(Qt::TextSelectableByMouse);
        ui->infoForm->addRow(e.value("name").toString() + QLatin1Char(':'), l);
    }
}

void HwmonPage::showValues()
{
    const QVariantList v = m_model->value(QStringLiteral("values")).toList();
    for (int i = 0; i < m_tiles.size(); ++i) {
        if (i < v.size() && v[i].typeId() == QMetaType::QString)
            m_tiles[i]->setText(v[i].toString());
        else if (i < v.size())
            m_tiles[i]->setValue(v[i].toDouble());
        else
            m_tiles[i]->clearValue();
    }
}

void HwmonPage::showStatus()
{
    using S = iwp::DeviceModel::Status;
    if (m_model->status() == S::Running) {
        ui->statusLabel->setText(tr("%1 sensors, every %2 ms")
                              .arg(m_model->value(QStringLiteral("sensor_count")).toInt())
                              .arg(m_model->value(QStringLiteral("period_ms")).toLongLong()));
    } else {
        ui->statusLabel->setText(m_model->statusMessage());
    }
}

void HwmonPage::apply()
{
    HwmonSettings s;
    s.periodMs = ui->periodSpin->value();
    s.precise = ui->preciseCheck->isChecked();
    s.sensorsText = ui->sensorsEdit->toPlainText();
    s.infoText = ui->infoEdit->toPlainText();
    hwmon::Config cfg;
    QString err;
    if (!s.toConfig(cfg, &err)) {
        ui->errorLabel->setText(err);
        return;
    }
    ui->errorLabel->clear();
    s.save();
    buildTiles(false);   // from the new settings now; the device reports its slots after the restart
    m_model->sendCommand(QStringLiteral("reload"));
}

void HwmonPage::refreshPresets()
{
    ui->presetCombo->clear();
    m_presetList = HwmonPreset::builtins();
    m_presetList += HwmonPreset::userPresets();
    ui->presetCombo->addItem(tr("Choose a preset..."));
    const int builtinCount = int(hwmon::builtinPresets().size());
    for (int i = 0; i < m_presetList.size(); ++i) {
        const HwmonPreset &p = m_presetList[i];
        ui->presetCombo->addItem(i < builtinCount ? p.name : tr("%1 (saved)").arg(p.name));
        ui->presetCombo->setItemData(i + 1, p.description, Qt::ToolTipRole);
    }
}

void HwmonPage::presetChosen(int index)
{
    if (index >= 1 && index <= m_presetList.size())
        loadPreset(m_presetList[index - 1]);
}

// Puts the preset into the editors only: it is not used (and not saved as the current settings) until "Apply".
void HwmonPage::loadPreset(const HwmonPreset &p)
{
    ui->sensorsEdit->setPlainText(p.sensorsText);
    ui->infoEdit->setPlainText(p.infoText);
    ui->periodSpin->setValue(p.periodMs);
    ui->preciseCheck->setChecked(p.precise);
    ui->errorLabel->clear();
    ui->presetNote->setText(tr("Loaded \"%1\". Press Apply to use it.").arg(p.name));
}

void HwmonPage::savePreset()
{
    QDir().mkpath(HwmonPreset::userDir());
    const QString path = QFileDialog::getSaveFileName(
        this, tr("Save preset"), HwmonPreset::userDir() + QLatin1Char('/') + HwmonPreset::fileNameFor(tr("my preset")),
        tr("hwmon presets (*.json)"));
    if (path.isEmpty())
        return;
    HwmonPreset p;
    p.name = QFileInfo(path).completeBaseName();
    p.periodMs = ui->periodSpin->value();
    p.precise = ui->preciseCheck->isChecked();
    p.sensorsText = ui->sensorsEdit->toPlainText();
    p.infoText = ui->infoEdit->toPlainText();
    // Do not save what could not be loaded back.
    hwmon::Config cfg;
    HwmonSettings check;
    check.periodMs = p.periodMs;
    check.sensorsText = p.sensorsText;
    check.infoText = p.infoText;
    QString err;
    if (!check.toConfig(cfg, &err)) {
        ui->errorLabel->setText(err);
        return;
    }
    QSaveFile f(path);
    if (!f.open(QIODevice::WriteOnly) || f.write(p.toJson()) < 0 || !f.commit()) {
        ui->errorLabel->setText(tr("Cannot write %1").arg(path));
        return;
    }
    ui->errorLabel->clear();
    ui->presetNote->setText(tr("Saved: %1").arg(QDir::toNativeSeparators(path)));
    refreshPresets();
}

void HwmonPage::openPreset()
{
    const QString path = QFileDialog::getOpenFileName(this, tr("Open preset"), HwmonPreset::userDir(),
                                                      tr("hwmon presets (*.json)"));
    if (path.isEmpty())
        return;
    QFile f(path);
    HwmonPreset p;
    QString err;
    if (!f.open(QIODevice::ReadOnly)) {
        ui->errorLabel->setText(tr("Cannot read %1").arg(path));
        return;
    }
    if (!HwmonPreset::fromJson(f.read(1 << 20), p, &err)) {
        ui->errorLabel->setText(tr("%1: %2").arg(QFileInfo(path).fileName(), err));
        return;
    }
    if (p.name.isEmpty())
        p.name = QFileInfo(path).completeBaseName();
    loadPreset(p);
}
